const subtotalFn = (items, discount = 0) => {
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk) * (1 - discount));
};
const items = Array.from({length:10},()=>({price:100,qty:1}));
console.log('10 lines, 10% discount: PR =', subtotalFn(items,0.1), 'spec =', Math.round(1000*0.9*0.95));
